query MyQuery {
  merchants(direction: FORWARD, limit: 10, offset: "", offset_id: "", query: {}) {
    items {
      updated_row_at
      submitted_onboarding
      parent_merchant_uid
      merchant_uid
      merchant_name
      is_system
      cash_active
      card_active
      ach_active
    }
    total_row_count
  }
}

